import{_ as e,o as s,c as a,ag as i}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Installation","description":"Install Muxit on Windows, macOS, or Linux — one command, no prerequisites.","frontmatter":{"title":"Installation","description":"Install Muxit on Windows, macOS, or Linux — one command, no prerequisites."},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),n={name:"getting-started/installation.md"};function o(r,t,l,d,h,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Get Muxit running on your machine in under a minute. Muxit ships a self-contained binary for <strong>Windows (x64)</strong>, <strong>macOS (Apple Silicon / Intel)</strong>, and <strong>Linux (x64 / ARM64)</strong> — no runtime to install.</p><h2 id="quick-install-recommended" tabindex="-1">Quick Install (Recommended) <a class="header-anchor" href="#quick-install-recommended" aria-label="Permalink to &quot;Quick Install (Recommended)&quot;">​</a></h2><p><strong>Windows</strong> — open PowerShell and run:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw.githubusercontent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>This downloads the latest release, extracts it to <code>%LOCALAPPDATA%\\muxit</code>, and adds it to your PATH.</p><p><strong>macOS / Linux</strong> — open a terminal and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/muxit-io/muxit/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>The same script detects your OS and CPU architecture and pulls the matching build — Apple Silicon (<code>osx-arm64</code>) or Intel (<code>osx-x64</code>) on macOS; <code>linux-x64</code> or <code>linux-arm64</code> on Linux. On macOS it also clears the Gatekeeper quarantine attribute so the unsigned binary launches. See the <a href="/guides/install-linux.html">Linux install guide</a> for distro-specific notes and the <a href="/getting-started/system-requirements.html#macos-notes">macOS notes</a> for what&#39;s supported.</p><p>No prerequisites required on any platform — the binary is fully self-contained.</p><h2 id="manual-download" tabindex="-1">Manual Download <a class="header-anchor" href="#manual-download" aria-label="Permalink to &quot;Manual Download&quot;">​</a></h2><p>If you prefer to install manually, grab the archive for your platform from the <a href="https://github.com/muxit-io/muxit/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> page (the file name includes the release version):</p><ul><li><strong>Windows</strong> — download <code>muxit-win-x64-v&lt;version&gt;.zip</code>, extract to a folder (e.g. <code>C:\\muxit</code>), and run <code>muxit.exe</code>.</li><li><strong>macOS</strong> — download <code>muxit-osx-arm64-v&lt;version&gt;.tar.gz</code> (Apple Silicon) or <code>muxit-osx-x64-v&lt;version&gt;.tar.gz</code> (Intel), extract it, run <code>xattr -dr com.apple.quarantine &lt;folder&gt;</code> once to clear Gatekeeper, then run <code>./muxit</code>.</li><li><strong>Linux</strong> — download <code>muxit-linux-x64-v&lt;version&gt;.tar.gz</code> or <code>muxit-linux-arm64-v&lt;version&gt;.tar.gz</code>, extract it, and run <code>./muxit</code>.</li></ul><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td><strong>OS</strong></td><td>Windows 10 or later (x64); macOS 12+ (Apple Silicon / Intel); Linux x64 / ARM64</td></tr><tr><td><strong>Runtime</strong></td><td>None — self-contained binary, no .NET or Node.js needed</td></tr><tr><td><strong>Disk space</strong></td><td>~150 MB</td></tr><tr><td><strong>Network</strong></td><td>Required for AI features and license activation; optional otherwise</td></tr></tbody></table><p>See <a href="/getting-started/system-requirements.html">System Requirements</a> for the full platform matrix and the macOS feature notes.</p><h2 id="first-run" tabindex="-1">First Run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First Run&quot;">​</a></h2><p>After installing, start Muxit:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span></span></code></pre></div><p>This starts the server and opens your default browser to <code>http://localhost:8765</code>.</p><p>On first run, you&#39;ll see the <strong>Workspace Setup</strong> screen. Create a new workspace or open an existing one to get started. See <a href="/guides/workspaces.html">Workspaces</a> for details.</p><p>Other start modes:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nogui               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start without opening browser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">no</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tray             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start without system tray icon</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Use a custom port</span></span></code></pre></div><h2 id="verify-it-works" tabindex="-1">Verify It Works <a class="header-anchor" href="#verify-it-works" aria-label="Permalink to &quot;Verify It Works&quot;">​</a></h2><p>Once the server is running and the browser opens:</p><ol><li><strong>Check the Hardware panel</strong> — Click the plug icon in the left Activity Bar. You should see <strong>test-device</strong> listed with live properties (temperature, label, count, etc.)</li><li><strong>Open a demo dashboard</strong> — In the Explorer sidebar, expand <code>dashboards/</code> and click <code>demo.dashboard.json</code>. You should see live gauges and widgets</li><li><strong>Run a script</strong> — In the Explorer sidebar, expand <code>scripts/</code> and click <code>hello.js</code>. Click the <strong>Run</strong> button in the editor toolbar. Check the Output panel at the bottom for log messages</li></ol><p>If you see the test device with updating values, Muxit is working correctly.</p><hr><h2 id="what-s-included" tabindex="-1">What&#39;s Included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s Included&quot;">​</a></h2><p>Muxit ships as a single self-contained package — no hardware needed to get started:</p><table tabindex="0"><thead><tr><th>Category</th><th>What&#39;s Included</th></tr></thead><tbody><tr><td><strong>MuxitServer</strong></td><td>Self-contained .NET 9.0 binary (no runtime install needed)</td></tr><tr><td><strong>Built-in drivers</strong></td><td>TestDevice, Webcam, ONVIF (IP camera), FileAccess, MqttBridge, WebhookNotifier, EmailNotifier</td></tr><tr><td><strong>Example connectors</strong></td><td>test-device, webcam, gui, store, and more in <code>workspace/connectors/</code></td></tr><tr><td><strong>Example scripts</strong></td><td>hello.js, examples/sinewave.js, examples/psu-voltage-ramp.js, the <code>tutorials/</code> series, and more</td></tr><tr><td><strong>Example dashboards</strong></td><td>demo, test-device, gcode, psu, and more</td></tr><tr><td><strong>Example agents</strong></td><td>temperature-monitor, pick-and-place</td></tr><tr><td><strong>Documentation</strong></td><td>Built-in at <code>/docs/</code> in the web UI</td></tr></tbody></table><p>The <strong>TestDevice</strong> is a simulated device that exercises every data type (strings, numbers, booleans, arrays, objects). It&#39;s always available and doesn&#39;t count against your connector limit — making it the perfect learning tool.</p><hr><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>The easiest way is straight from the app: <strong>Help → Check for Updates…</strong>. When a newer release is available, Muxit downloads it, installs it in place, and restarts onto the new version automatically — the page reconnects on its own when the server is back, and no second browser tab is opened. Your workspace files (connectors, scripts, dashboards, agents, config) are preserved; everything the release ships — the binary, its runtime files, the web UI under <code>wwwroot/</code> and <code>workspace-template/</code> — is replaced. The previous version is kept in a <code>.muxit-update-backup/</code> folder next to the binary until the update has been applied, and is removed on the next start.</p><p>In-app self-install works on Windows x64, Linux x64, Linux arm64, macOS x64 and macOS arm64. On other platforms (or builds that can&#39;t self-install) the menu offers a download link instead.</p><p>You can also update from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Or re-run the platform installer, which detects the existing installation and updates in place:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw.githubusercontent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>Muxit also checks for updates automatically on startup and surfaces them in the Help menu.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Installer fails to download</strong> — Check your internet connection. The installer fetches from GitHub Releases. Corporate firewalls may block <code>raw.githubusercontent.com</code>.</p><p><strong>Port 8765 already in use</strong> — Another instance of Muxit (or another program) is using the port. Stop the other process or use <code>--port=9000</code> to pick a different port.</p><p><strong><code>muxit</code> command not found after install</strong> — Close and reopen your terminal. The installer adds the install directory to your user PATH, but existing terminal sessions need to be restarted.</p><p><strong>Windows SmartScreen warning</strong> — On first run, Windows may show a SmartScreen warning because the binary isn&#39;t code-signed yet. Click &quot;More info&quot; then &quot;Run anyway&quot;.</p><p><strong>No system tray icon on Windows</strong> — the tray&#39;s native library needs the Microsoft Visual C++ Redistributable (x64), which a clean Windows image does not have; Windows Sandbox is where this usually shows up. Install it from <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">https://aka.ms/vs/17/release/vc_redist.x64.exe</a> and restart Muxit. <code>install.ps1</code> does this for you. Nothing else depends on it — without the runtime the server runs normally, just without the tray icon, and the startup log says so.</p><p><strong>No window appears on Windows</strong> — This is expected. Muxit runs in the background behind its system tray icon (near the clock) rather than in a console window, so there&#39;s no terminal to accidentally close. Right-click the tray icon for <strong>Open GUI</strong> and <strong>View Logs</strong>, or browse to <code>http://localhost:8765</code>. Running <code>muxit</code> from a terminal still prints its logs there.</p><p><strong>macOS &quot;cannot be opened&quot; / Gatekeeper</strong> — The macOS builds aren&#39;t notarized yet, so Gatekeeper quarantines a downloaded archive. The install script clears this for you; if you extracted a <code>.tar.gz</code> by hand, run <code>xattr -dr com.apple.quarantine &lt;install-dir&gt;</code> once, then launch <code>./muxit</code>.</p><p>For more help, see the <a href="/guides/troubleshooting.html">Troubleshooting Guide</a>.</p>`,51)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
